//! Syntax-highlighted, read-only preview of Svelte code drawn on a `Canvas`.
//!
//! Highlighting is a lightweight tokenizer (markup + script + css) — enough
//! to preview code generated by `codegen::to_svelte`. Editing happens in a
//! separate mode on `TextArea` (see `panels/properties/code.rs`).

use std::cell::RefCell;
use std::rc::Rc;

use sequoia_ui::prelude::*;
use sequoia_ui::view::Fill;

// ──────────────────────────────── model ────────────────────────────────

/// A fragment of a line with its own color.
#[derive(Clone, Debug, PartialEq)]
pub(crate) struct Run {
    pub(crate) text: String,
    pub(crate) color: Color,
}

impl Run {
    fn new(text: &str, color: Color) -> Self {
        Self {
            text: text.to_string(),
            color,
        }
    }
}

/// A highlighted line of code.
#[derive(Clone, Debug, PartialEq, Default)]
pub(crate) struct HlLine {
    pub(crate) runs: Vec<Run>,
}

impl HlLine {
    pub(crate) fn text(&self) -> String {
        self.runs.iter().map(|r| r.text.as_str()).collect()
    }
}

/// Splits text into lines, appending colored fragments.
fn push_text(lines: &mut Vec<HlLine>, text: &str, color: Color) {
    let mut first = true;
    for piece in text.split('\n') {
        if !first {
            lines.push(HlLine::default());
        }
        if !piece.is_empty() {
            if let Some(last) = lines.last_mut() {
                last.runs.push(Run::new(piece, color));
            }
        }
        first = false;
    }
}

// ──────────────────────────────── colors ────────────────────────────────

const C_BASE: u32 = 0xD4D4D4; // plain text
const C_TAG: u32 = 0x569CD6; // tag names
const C_BRACKET: u32 = 0x808080; // < > / = { } : ;
const C_ATTR: u32 = 0x9CDCFE; // attributes and CSS properties
const C_STRING: u32 = 0xCE9178; // literals
const C_COMMENT: u32 = 0x6A9955; // comments
const C_KEYWORD: u32 = 0xC586C0; // script keywords
const C_SELECTOR: u32 = 0xD7BA7D; // CSS selectors
const C_NUMBER: u32 = 0xB5CEA8; // numbers

fn c(v: u32) -> Color {
    Color::hex(v)
}

// ──────────────────────────────── tokenizer ────────────────────────────────

/// Highlights Svelte code and splits it into lines.
pub(crate) fn highlight_svelte(src: &str) -> Vec<HlLine> {
    let chars: Vec<char> = src.chars().collect();
    let n = chars.len();
    let mut lines: Vec<HlLine> = vec![HlLine::default()];
    let mut i = 0;

    while i < n {
        let rest: String = chars[i..(i + 16).min(n)].iter().collect();
        if rest.starts_with("<!--") {
            // HTML comment until -->
            match find_seq(&chars, i + 4, "-->") {
                Some(end) => {
                    push_text(&mut lines, &chars[i..end + 3].iter().collect::<String>(), c(C_COMMENT));
                    i = end + 3;
                }
                None => {
                    push_text(&mut lines, &chars[i..].iter().collect::<String>(), c(C_COMMENT));
                    i = n;
                }
            }
        } else if rest.starts_with('<') {
            let after: String = chars[i + 1..].iter().collect::<String>();
            let lower = after.to_lowercase();
            if lower.starts_with("script") {
                let end_all = find_ci(&chars, i, "</script>")
                    .map(|e| (e + "</script>".len()).min(n))
                    .unwrap_or(n);
                let block: String = chars[i..end_all].iter().collect();
                highlight_script_block(&block, &mut lines);
                i = end_all;
            } else if lower.starts_with("style") {
                let end_all = find_ci(&chars, i, "</style>")
                    .map(|e| (e + "</style>".len()).min(n))
                    .unwrap_or(n);
                let block: String = chars[i..end_all].iter().collect();
                highlight_css_block(&block, &mut lines);
                i = end_all;
            } else {
                i = highlight_tag(&chars, i, &mut lines);
            }
        } else {
            let take = chars[i..].iter().position(|&ch| ch == '<').unwrap_or(n - i);
            let text: String = chars[i..i + take].iter().collect();
            push_text(&mut lines, &text, c(C_BASE));
            i += take;
        }
    }

    lines
}

/// Highlights a single tag `<div class="x">`; returns the new position.
fn highlight_tag(chars: &[char], start: usize, lines: &mut Vec<HlLine>) -> usize {
    let n = chars.len();
    let mut i = start;
    push_text(lines, "<", c(C_BRACKET));
    i += 1;
    let mut first_word = true;

    while i < n {
        let ch = chars[i];
        if ch == '>' {
            push_text(lines, ">", c(C_BRACKET));
            return i + 1;
        }
        if ch.is_whitespace() {
            push_text(lines, " ", c(C_BRACKET));
            i += 1;
        } else if ch == '"' || ch == '\'' {
            let quote = ch;
            let take = chars[i + 1..]
                .iter()
                .position(|&c2| c2 == quote)
                .map(|p| p + 2)
                .unwrap_or(n - i);
            let text: String = chars[i..(i + take).min(n)].iter().collect();
            push_text(lines, &text, c(C_STRING));
            i += take;
        } else if ch.is_ascii_digit() {
            let take = chars[i..]
                .iter()
                .take_while(|c2| c2.is_ascii_digit() || **c2 == '.')
                .count();
            let text: String = chars[i..i + take].iter().collect();
            push_text(lines, &text, c(C_NUMBER));
            i += take;
        } else if ch.is_alphanumeric() || ch == '-' || ch == '_' {
            let take = chars[i..]
                .iter()
                .take_while(|c2| c2.is_alphanumeric() || **c2 == '-' || **c2 == '_')
                .count();
            let word: String = chars[i..i + take].iter().collect();
            // first word in a tag = tag name; later ones followed by '=' = attributes
            let is_attr = !first_word && eq_ahead(chars, i + take);
            push_text(
                lines,
                &word,
                c(if is_attr { C_ATTR } else { C_TAG }),
            );
            first_word = false;
            i += take;
        } else {
            push_text(lines, &chars[i].to_string(), c(C_BRACKET));
            i += 1;
        }
    }
    n
}

fn eq_ahead(chars: &[char], mut pos: usize) -> bool {
    while pos < chars.len() {
        match chars[pos] {
            ' ' | '\t' | '\n' | '\r' => pos += 1,
            '=' => return true,
            _ => return false,
        }
    }
    false
}

/// Highlights a `<script>...</script>` block (comments, strings, keywords).
fn highlight_script_block(block: &str, lines: &mut Vec<HlLine>) {
    const KEYWORDS: &[&str] = &[
        "const", "let", "var", "function", "return", "if", "else", "export", "import", "true",
        "false", "null", "async", "await", "for", "of", "in", "new", "class",
    ];
    let chars: Vec<char> = block.chars().collect();
    let n = chars.len();
    let mut i = 0;

    while i < n {
        let rest: String = chars[i..(i + 12).min(n)].iter().collect();
        if rest.starts_with("//") {
            let take = chars[i..].iter().position(|&c2| c2 == '\n').unwrap_or(n - i);
            push_text(lines, &chars[i..i + take].iter().collect::<String>(), c(C_COMMENT));
            i += take;
        } else if rest.starts_with("/*") {
            match find_seq(&chars, i + 2, "*/") {
                Some(e) => {
                    push_text(lines, &chars[i..e + 2].iter().collect::<String>(), c(C_COMMENT));
                    i = e + 2;
                }
                None => {
                    push_text(lines, &chars[i..].iter().collect::<String>(), c(C_COMMENT));
                    i = n;
                }
            }
        } else if chars[i] == '"' || chars[i] == '\'' || chars[i] == '`' {
            let quote = chars[i];
            let take = chars[i + 1..]
                .iter()
                .position(|&c2| c2 == quote)
                .map(|p| p + 2)
                .unwrap_or(n - i);
            push_text(
                lines,
                &chars[i..(i + take).min(n)].iter().collect::<String>(),
                c(C_STRING),
            );
            i += take;
        } else if chars[i].is_alphabetic() || chars[i] == '_' {
            let take = chars[i..]
                .iter()
                .take_while(|c2| c2.is_alphanumeric() || **c2 == '_')
                .count();
            let word: String = chars[i..i + take].iter().collect();
            let color = if KEYWORDS.contains(&word.as_str()) {
                C_KEYWORD
            } else {
                C_BASE
            };
            push_text(lines, &word, c(color));
            i += take;
        } else if chars[i].is_ascii_digit() {
            let take = chars[i..]
                .iter()
                .take_while(|c2| c2.is_ascii_digit() || **c2 == '.')
                .count();
            push_text(lines, &chars[i..i + take].iter().collect::<String>(), c(C_NUMBER));
            i += take;
        } else if chars[i] == '<' {
            // opening/closing tag <script lang="ts"> and </script>
            i = highlight_tag(&chars, i, lines);
        } else {
            push_text(lines, &chars[i].to_string(), c(C_BASE));
            i += 1;
        }
    }
}

/// Highlights a `<style>...</style>` block: selectors, properties, values, numbers.
fn highlight_css_block(block: &str, lines: &mut Vec<HlLine>) {
    let chars: Vec<char> = block.chars().collect();
    let n = chars.len();
    let mut i = 0;
    let mut in_braces = false;
    let mut after_colon = false;

    while i < n {
        let rest: String = chars[i..(i + 12).min(n)].iter().collect();
        if rest.starts_with("/*") {
            match find_seq(&chars, i + 2, "*/") {
                Some(e) => {
                    push_text(lines, &chars[i..e + 2].iter().collect::<String>(), c(C_COMMENT));
                    i = e + 2;
                }
                None => {
                    push_text(lines, &chars[i..].iter().collect::<String>(), c(C_COMMENT));
                    i = n;
                }
            }
        } else if rest.starts_with("<style") || rest.starts_with("</style") {
            let take = chars[i..].iter().position(|&c2| c2 == '>').map(|p| p + 1).unwrap_or(n - i);
            push_text(lines, &chars[i..i + take].iter().collect::<String>(), c(C_TAG));
            i += take;
        } else {
            let ch = chars[i];
            match ch {
                '{' => {
                    in_braces = true;
                    after_colon = false;
                    push_text(lines, "{", c(C_BRACKET));
                    i += 1;
                }
                '}' => {
                    in_braces = false;
                    after_colon = false;
                    push_text(lines, "}", c(C_BRACKET));
                    i += 1;
                }
                ':' => {
                    if in_braces {
                        after_colon = true;
                        push_text(lines, ":", c(C_BRACKET));
                    } else {
                        push_text(lines, ":", c(C_BASE));
                    }
                    i += 1;
                }
                ';' => {
                    after_colon = false;
                    push_text(lines, ";", c(C_BRACKET));
                    i += 1;
                }
                c2 if c2.is_whitespace() => {
                    push_text(lines, &c2.to_string(), c(C_BASE));
                    i += 1;
                }
                _ => {
                    let take = chars[i..]
                        .iter()
                        .take_while(|c3| {
                            !c3.is_whitespace()
                                && !matches!(**c3, '{' | '}' | ':' | ';' | '/' | '<')
                        })
                        .count();
                    let word: String = chars[i..i + take].iter().collect();
                    let color = if !in_braces {
                        C_SELECTOR
                    } else if after_colon {
                        if word.chars().all(|c3| c3.is_ascii_digit() || c3 == '.')
                            && word.chars().any(|c3| c3.is_ascii_digit())
                        {
                            C_NUMBER
                        } else {
                            C_STRING
                        }
                    } else {
                        C_ATTR
                    };
                    push_text(lines, &word, c(color));
                    i += take;
                }
            }
        }
    }
}

fn find_seq(chars: &[char], from: usize, pat: &str) -> Option<usize> {
    let pat: Vec<char> = pat.chars().collect();
    let pl = pat.len();
    if pl == 0 || chars.len() < pl {
        return None;
    }
    (from..=chars.len() - pl).find(|&start| chars[start..start + pl] == pat[..])
}

fn find_ci(chars: &[char], from: usize, pat: &str) -> Option<usize> {
    let pat_lower: Vec<char> = pat.to_lowercase().chars().collect();
    let pl = pat_lower.len();
    if pl == 0 || chars.len() < pl {
        return None;
    }
    for start in from..=chars.len() - pl {
        let win: Vec<char> = chars[start..start + pl]
            .iter()
            .map(|c2| c2.to_ascii_lowercase())
            .collect();
        if win == pat_lower {
            return Some(start);
        }
    }
    None
}

// ──────────────────────────────── widget ────────────────────────────────

const FONT: &str = "IBM Plex Mono";
const FONT_SIZE: f32 = 11.0;
const GUTTER_W: f32 = 34.0;
const PAD: f32 = 8.0;

/// Read-only code preview with line numbers, scrolling and a scrollbar.
pub(crate) fn code_view(code: Signal<String>) -> impl View + 'static {
    let scroll_y = Signal::new(0.0f32);
    let scroll_x = Signal::new(0.0f32);
    let drag_last_y: Rc<RefCell<Option<f32>>> = Rc::new(RefCell::new(None));
    let drag_last_x: Rc<RefCell<Option<f32>>> = Rc::new(RefCell::new(None));

    let track_code = code.clone();
    let track_sy = scroll_y.clone();
    let track_sx = scroll_x.clone();

    let draw_code = code.clone();
    let draw_sy = scroll_y.clone();
    let draw_sx = scroll_x.clone();

    Canvas::new()
        .background(Color::hex(0x141416))
        .fill_size()
        .track(move || {
            track_code.get();
            track_sy.get();
            track_sx.get();
        })
        .on_draw(move |p| {
            let src = draw_code.get_untracked();
            let lines = highlight_svelte(&src);
            let size = p.size();
            let metrics = p.text_metrics(FONT_SIZE);
            let line_h = (metrics.height * 1.35).max(FONT_SIZE * 1.45);
            let char_w = p.text_width("0", FONT_SIZE).max(1.0);

            let mut content_w = 40.0f32;
            for l in &lines {
                let w = l.runs.iter().map(|r| r.text.chars().count() as f32).sum::<f32>() * char_w;
                content_w = content_w.max(w);
            }
            let content_h = lines.len() as f32 * line_h + PAD * 2.0;
            let view_h = size.height.max(1.0);
            let view_w = (size.width - GUTTER_W).max(1.0);
            let max_y = (content_h - view_h).max(0.0);
            let max_x = (content_w - view_w).max(0.0);

            let sy = draw_sy.get_untracked().clamp(0.0, max_y);
            let sx = draw_sx.get_untracked().clamp(0.0, max_x);

            // gutter background with line numbers
            p.fill(
                Rect::from_xywh(0.0, 0.0, GUTTER_W, size.height),
                Fill::solid(Color::hex(0x111113)),
            );

            let first_line = (sy / line_h).floor() as usize;
            let visible = ((view_h / line_h).ceil() as usize + 1).min(lines.len());

            for idx in 0..visible {
                let li = first_line + idx;
                if li >= lines.len() {
                    break;
                }
                let y = PAD + li as f32 * line_h - sy;
                let num = format!("{}", li + 1);
                let num_w = p.text_width(&num, FONT_SIZE);
                p.text_tl(
                    &num,
                    Point::new(GUTTER_W - num_w - 6.0, y),
                    FONT_SIZE,
                    c(0x5A5A5E),
                );
                let mut x = GUTTER_W + PAD - sx;
                for r in &lines[li].runs {
                    p.text_tl(&r.text, Point::new(x, y), FONT_SIZE, r.color);
                    x += r.text.chars().count() as f32 * char_w;
                }
            }

            // scrollbar (vertical)
            if content_h > view_h && max_y > 0.0 {
                let bar_h = (view_h * view_h / content_h).max(24.0);
                let bar_y = sy / max_y * (view_h - bar_h);
                p.fill(
                    Rect::from_xywh(size.width - 3.0, bar_y, 3.0, bar_h),
                    Fill::solid(c(0x3A3A3E)),
                );
            }

            // store clamped offsets (so dragging doesn't run away)
            if (draw_sy.get_untracked() - sy).abs() > 0.01 {
                draw_sy.set(sy);
            }
            if (draw_sx.get_untracked() - sx).abs() > 0.01 {
                draw_sx.set(sx);
            }
        })
        .on_pointer(move |pos, ev, ctx| match ev {
            PointerEvent::Wheel { delta, modifiers, .. } => {
                if modifiers.contains(Modifiers::SHIFT) {
                    scroll_x.update(|v| *v += delta.y);
                } else {
                    scroll_y.update(|v| *v += delta.y);
                }
                ctx.handled();
            }
            PointerEvent::Down { button, .. } => {
                if *button == PointerButton::Left {
                    *drag_last_y.borrow_mut() = Some(pos.y);
                    *drag_last_x.borrow_mut() = Some(pos.x);
                    ctx.handled();
                }
            }
            PointerEvent::Move { .. } => {
                let mut moved = false;
                if let Some(last) = drag_last_y.borrow_mut().as_mut() {
                    let dy = *last - pos.y;
                    *last = pos.y;
                    scroll_y.update(|v| *v += dy);
                    moved = true;
                }
                if let Some(last) = drag_last_x.borrow_mut().as_mut() {
                    let dx = *last - pos.x;
                    *last = pos.x;
                    scroll_x.update(|v| *v += dx);
                    moved = true;
                }
                if moved {
                    ctx.handled();
                }
            }
            PointerEvent::Up { .. } => {
                *drag_last_y.borrow_mut() = None;
                *drag_last_x.borrow_mut() = None;
            }
            _ => {}
        })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn empty_input_single_line() {
        let lines = highlight_svelte("");
        assert_eq!(lines.len(), 1);
        assert!(lines[0].runs.is_empty());
    }

    #[test]
    fn tag_and_attribute_are_colored() {
        let lines = highlight_svelte("<div class=\"box\">Hi</div>\n");
        assert!(lines.len() >= 2, "expected at least 2 lines");
        let joined: Vec<String> = lines.iter().map(|l| l.text()).collect();
        assert_eq!(joined[0], "<div class=\"box\">Hi</div>");
        // tag name uses the tag color, attribute uses the attribute color
        let has_tag = lines[0].runs.iter().any(|r| r.text == "div" && r.color == c(C_TAG));
        let has_attr = lines[0].runs.iter().any(|r| r.text == "class" && r.color == c(C_ATTR));
        let has_str = lines[0].runs.iter().any(|r| r.text == "\"box\"" && r.color == c(C_STRING));
        assert!(has_tag, "tag name is not colored: {:?}", lines[0].runs);
        assert!(has_attr, "attribute is not colored: {:?}", lines[0].runs);
        assert!(has_str, "string attribute is not colored: {:?}", lines[0].runs);
    }

    #[test]
    fn html_comment_is_commented() {
        let lines = highlight_svelte("<!-- hi -->");
        assert!(lines[0]
            .runs
            .iter()
            .all(|r| r.color == c(C_COMMENT)));
    }

    #[test]
    fn css_block_colors_selectors_and_props() {
        let src = "<style>\n.box {\n  color: #FF0000;\n}\n</style>";
        let lines = highlight_svelte(src);
        let all_runs: Vec<&Run> = lines.iter().flat_map(|l| l.runs.iter()).collect();
        assert!(all_runs.iter().any(|r| r.text == ".box" && r.color == c(C_SELECTOR)));
        assert!(all_runs.iter().any(|r| r.text == "color" && r.color == c(C_ATTR)));
        assert!(all_runs.iter().any(|r| r.text == "#FF0000" && r.color == c(C_STRING)));
    }

    #[test]
    fn script_block_keeps_comments_and_keywords() {
        let src = "<script lang=\"ts\">\n  // generated\n  const x = 1;\n</script>";
        let lines = highlight_svelte(src);
        let all_runs: Vec<&Run> = lines.iter().flat_map(|l| l.runs.iter()).collect();
        assert!(all_runs.iter().any(|r| r.text.contains("generated") && r.color == c(C_COMMENT)));
        assert!(all_runs.iter().any(|r| r.text == "const" && r.color == c(C_KEYWORD)));
    }
}
